107:     return done();
108:   }
109:   var method = typeof req.method === 'string'
110:     ? req.method.toLowerCase()
111:     : req.method
112: 
113:   if (method === 'head' && !this.methods['head']) {
114:     method = 'get';
115:   }
116: 
